<?php session_start();require_once __DIR__.'/../config/config.php';$userId=(int)($_SESSION['user_id']??0);if(!$userId){header('Location: /pages/login.php');exit;}function wImg(?string $v):?string{if(!$v)return null;if(preg_match('#^https?://#i',$v))return $v;$v=ltrim(str_replace('\\','/',$v),'/');if(str_starts_with($v,'pages/'))return '/'.$v;if(str_starts_with($v,'uploads/'))return '/pages/'.$v;return '/assets/image/books/'.$v;}$tab=$_GET['tab']??'new';$page=max(1,(int)($_GET['page']??1));$limit=20;$offset=($page-1)*$limit;
if($tab==='exchange'){$count=$pdo->prepare('SELECT COUNT(*) FROM exchange_wishlists WHERE user_id=?');$count->execute([$userId]);$total=(int)$count->fetchColumn();$stmt=$pdo->prepare("SELECT e.exchange_id id,e.title,e.author,0 price,e.image_cover, 1 as stock_quantity FROM exchange_wishlists w JOIN exchanges e ON e.exchange_id=w.exchange_id WHERE w.user_id=? ORDER BY w.created_at DESC LIMIT ? OFFSET ?");$stmt->bindValue(1,$userId);$stmt->bindValue(2,$limit,PDO::PARAM_INT);$stmt->bindValue(3,$offset,PDO::PARAM_INT);}else{$condition=$tab==='new'?'new':'used';$count=$pdo->prepare("SELECT COUNT(*) FROM wishlists w JOIN books b ON b.book_id=w.book_id WHERE w.user_id=? AND ".($tab==='new'?"(b.book_type='new' OR b.condition_level='new')":"b.book_type='used' AND b.condition_level<>'new'"));$count->execute([$userId]);$total=(int)$count->fetchColumn();$stmt=$pdo->prepare("SELECT b.book_id id,b.title,b.author,b.price,b.image_cover,b.condition_level,b.stock_quantity FROM wishlists w JOIN books b ON b.book_id=w.book_id WHERE w.user_id=? AND ".($tab==='new'?"(b.book_type='new' OR b.condition_level='new')":"b.book_type='used' AND b.condition_level<>'new'")." ORDER BY w.created_at DESC LIMIT ? OFFSET ?");$stmt->bindValue(1,$userId);$stmt->bindValue(2,$limit,PDO::PARAM_INT);$stmt->bindValue(3,$offset,PDO::PARAM_INT);}$stmt->execute();$rows=$stmt->fetchAll(PDO::FETCH_ASSOC);$pages=max(1,(int)ceil($total/$limit));
?>
<!DOCTYPE html><html lang="th"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>รายการโปรด - วนวรรณ</title><link rel="stylesheet" href="../assets/css/styles.css"><style>*{box-sizing:border-box}.wrap{max-width:1160px;margin:auto;padding:54px 40px 80px}.head{display:flex;justify-content:space-between;align-items:end;margin-bottom:44px}.head h1{color:var(--secondary-color);font-size:32px;margin:0}.head p{color:var(--text-muted);margin:5px 0}.tabs{display:flex;border:1px solid #d8ddd4;border-radius:9px;padding:6px}.tabs a{padding:10px 28px;border-radius:7px;text-decoration:none;color:var(--text-dark)}.tabs .active{background:var(--secondary-color);color:#fff}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:20px}.empty{grid-column:1/-1;text-align:center;padding:80px;color:var(--text-muted)}.pagination{display:flex;justify-content:center;gap:10px;margin-top:45px}.pagination a{width:44px;height:44px;border:1px solid var(--secondary-color);border-radius:8px;display:grid;place-items:center;text-decoration:none;color:var(--secondary-color)}.pagination .active{background:var(--secondary-color);color:#fff}@media(max-width:900px){.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.wrap{padding:35px 18px}.head{align-items:flex-start;flex-direction:column;gap:20px}.tabs a{padding:9px 15px}.grid{grid-template-columns:1fr}}</style></head><body><?php require __DIR__.'/../components/header.php';?><main class="wrap"><div class="head"><div><h1>รายการที่ชอบ</h1><p>คลังหนังสือส่วนตัวที่คุณบันทึกไว้เพื่อการค้นพบในอนาคต</p></div><nav class="tabs"><a class="<?=$tab==='new'?'active':''?>" href="?tab=new">หนังสือใหม่</a><a class="<?=$tab==='used'?'active':''?>" href="?tab=used">หนังสือมือสอง</a><a class="<?=$tab==='exchange'?'active':''?>" href="?tab=exchange">แลกเปลี่ยน</a></nav></div><div class="grid"><?php if(!$rows):?><p class="empty">ยังไม่มีหนังสือในรายการโปรดหมวดนี้</p><?php else:foreach($rows as $r){$book=['id'=>$r['id'],'title'=>$r['title'],'author'=>$r['author']??'','price'=>$r['price']??0,'badge'=>$tab==='exchange'?'แลกเปลี่ยน':'มาใหม่','image'=>wImg($r['image_cover']??null),'wishlisted'=>true,'stock_quantity'=>$r['stock_quantity']??1];$card_type=$tab==='exchange'?'exchange':($tab==='new'?'new':'used');require __DIR__.'/../components/book_card.php';}endif;?></div><?php if($pages>1):?><nav class="pagination"><?php for($p=1;$p<=$pages;$p++):?><a class="<?=$p===$page?'active':''?>" href="?tab=<?=$tab?>&page=<?=$p?>"><?=$p?></a><?php endfor;?></nav><?php endif;?></main><?php require __DIR__.'/../components/footer.php';?></body></html>
